bounded_host_request.command:
set -euo pipefail
image=create-videobot:local-poll
docker image inspect "$image" >/dev/null 2>&1 || exit 61
docker run --rm -i --network none --pull never --read-only --cap-drop ALL \
 --security-opt no-new-privileges:true --tmpfs /tmp:rw,nosuid,nodev,size=256m,mode=1777 \
 --entrypoint node "$image" --input-type=module <<'JS'
import {mkdtemp,rm} from 'node:fs/promises';
import {join} from 'node:path';
import {execFileSync} from 'node:child_process';
import {convertStickerMedia} from './src/stickers/mediaConverter.mjs';
const dir=await mkdtemp('/tmp/stk04-image-e2e-');
let s,e,v,ve;
const ff=(...a)=>execFileSync('ffmpeg',['-hide_banner','-loglevel','error','-nostdin','-y',...a],{timeout:30000,stdio:'ignore'});
try{
 const jpg=join(dir,'input.jpg'),mp4=join(dir,'input.mp4');
 ff('-f','lavfi','-i','color=c=red:s=800x600:d=1','-frames:v','1',jpg);
 s=await convertStickerMedia({sourcePath:jpg,kind:'sticker'});
 e=await convertStickerMedia({sourcePath:jpg,kind:'emoji'});
 if(s.format!=='static'||s.check.codec!=='png'||s.check.width!==512||s.check.height!==384)process.exitCode=80;
 if(e.format!=='static'||e.check.codec!=='png'||e.check.width!==100||e.check.height!==100)process.exitCode=81;
 ff('-f','lavfi','-i','color=c=blue:s=320x240:r=15:d=3.6','-c:v','mpeg4','-q:v','5',mp4);
 v=await convertStickerMedia({sourcePath:mp4,kind:'sticker'});
 ve=await convertStickerMedia({sourcePath:mp4,kind:'emoji'});
 if(v.format!=='video'||v.check.codec!=='vp9'||v.check.width!==512||v.check.height!==384||v.check.bytes>256*1024)process.exitCode=82;
 if(ve.format!=='video'||ve.check.codec!=='vp9'||ve.check.width!==100||ve.check.height!==100||ve.check.bytes>256*1024)process.exitCode=83;
 if(!process.exitCode)console.log('STK04_LIVE_IMAGE_FFMPEG_STATIC_VIDEO=PASS');
}catch(e){
 if(!process.exitCode)process.exitCode=84;
}finally{
 await s?.cleanup();await e?.cleanup();await v?.cleanup();await ve?.cleanup();
 await rm(dir,{recursive:true,force:true});
}
JS
